function esc(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}
function qty(value) {
  return Number(value || 0).toFixed(4);
}
function render(model) {
  const h = model.header || {};
  const items = Array.isArray(model.items) ? model.items : [];
  const totalRequired = items.reduce((sum, r) => sum + Number(r.requiredQuantity || 0), 0);
  const totalPicked = items.reduce((sum, r) => sum + Number(r.pickedQuantity || 0), 0);
  const totalRemaining = items.reduce((sum, r) => sum + Number(r.remainingQuantity || 0), 0);
  const rows = items.map(r => `
    <tr>
      <td>${esc(r.lineNo)}</td>
      <td>
        <div class="product-code">${esc(r.productCode)}</div>
        <div>${esc(r.productName)}</div>
        <div class="small">${esc(r.barcode || r.sku || "")}</div>
      </td>
      <td>${esc(r.pickLocations || "No location assigned")}</td>
      <td class="right">${qty(r.requiredQuantity)}</td>
      <td class="right">${qty(r.pickedQuantity)}</td>
      <td class="right">${qty(r.remainingQuantity)}</td>
      <td>${esc(r.unitCode)}</td>
      <td class="center"><span class="check-cell"></span></td>
    </tr>
  `).join("");
  document.getElementById("printRoot").innerHTML = `
    <div class="print-actions">
      <button class="print-btn" id="printBtn">Print</button>
    </div>

    <div class="print-page">
      <div class="header">
        <div class="company">
          ${h.companyLogoPath ? `<img class="logo" src="${esc(h.companyLogoPath)}">` : ""}
          <div>
            <div class="company-name">${esc(h.companyLegalName || h.companyName || "")}</div>
            <div class="muted">${esc(h.companyAddressLine1 || "")}</div>
            <div class="muted">${esc([h.companyPostalCode, h.companyCity, h.companyCountryCode].filter(Boolean).join(" "))}</div>
            <div class="muted">Tax No: ${esc(h.companyTaxNumber || "")}</div>
            <div class="muted">${esc(h.companyEmail || "")} ${esc(h.companyPhone || "")}</div>
          </div>
        </div>

        <div class="doc-title">
          <h1>Pick List</h1>
          <div class="doc-number">${esc(h.issueNumber || "")}</div>
          <div class="status">${esc(h.status || "")}</div>
        </div>
      </div>

      <div class="info-grid">
        <div class="info-box">
          <span>Issue Date</span>
          <b>${esc(h.issueDate || "")}</b>
        </div>
        <div class="info-box">
          <span>Warehouse</span>
          <b>${esc(h.warehouseCode || "")} - ${esc(h.warehouseName || "")}</b>
        </div>
        <div class="info-box">
          <span>Printed By</span>
          <b>${esc(model.username || h.createdByUsername || "")}</b>
        </div>
      </div>

      <table class="pick-table">
        <thead>
          <tr>
            <th>#</th>
            <th>Product</th>
            <th>Pick Location</th>
            <th class="right">Required</th>
            <th class="right">Picked</th>
            <th class="right">Remaining</th>
            <th>Unit</th>
            <th class="center">OK</th>
          </tr>
        </thead>
        <tbody>
          ${rows || `<tr><td colspan="8">No items found.</td></tr>`}
        </tbody>
      </table>

      <table class="summary">
        <tr><td>Total Required</td><td class="right"><b>${qty(totalRequired)}</b></td></tr>
        <tr><td>Total Picked</td><td class="right"><b>${qty(totalPicked)}</b></td></tr>
        <tr><td>Total Remaining</td><td class="right"><b>${qty(totalRemaining)}</b></td></tr>
      </table>

      ${h.note ? `<div class="note"><b>Note:</b> ${esc(h.note)}</div>` : ""}

      <div class="signatures">
        <div class="signature">Picked by</div>
        <div class="signature">Checked by</div>
      </div>
    </div>
  `;
  document.getElementById("printBtn").onclick = function () {
    window.print();
  };
}
if (window.appsmith && appsmith.onReady) {
  appsmith.onReady(() => {
    render(appsmith.model || {});
  });
}
if (window.appsmith && appsmith.onModelChange) {
  appsmith.onModelChange(model => {
    render(model || {});
  });
}
setTimeout(() => {
  render(window.appsmith?.model || {});
}, 300);

